#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 120
#define NC 256

typedef float v8 __attribute__((vector_size(32)));
typedef float v8u __attribute__((vector_size(32), aligned(4)));

static inline v8 bcast(float x) {
    v8 r = {x, x, x, x, x, x, x, x};
    return r;
}

/* Computes a MR x NR tile: acc = a(MR x kc) * b(kc x NR), packed formats.
   Writes to c (ldc) if full, else into tmp then copies valid part. */
static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int first)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b);
        v8 b1 = *(const v8 *)(b + 8);
        v8 a0 = bcast(a[0]);
        c00 += a0 * b0; c01 += a0 * b1;
        v8 a1 = bcast(a[1]);
        c10 += a1 * b0; c11 += a1 * b1;
        v8 a2 = bcast(a[2]);
        c20 += a2 * b0; c21 += a2 * b1;
        v8 a3 = bcast(a[3]);
        c30 += a3 * b0; c31 += a3 * b1;
        v8 a4 = bcast(a[4]);
        c40 += a4 * b0; c41 += a4 * b1;
        v8 a5 = bcast(a[5]);
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
#define ST(r, x0, x1) do { \
            v8u *p0 = (v8u *)(c + (r) * ldc); \
            v8u *p1 = (v8u *)(c + (r) * ldc + 8); \
            if (first) { *p0 = x0; *p1 = x1; } \
            else { *p0 += x0; *p1 += x1; } \
        } while (0)
        ST(0, c00, c01); ST(1, c10, c11); ST(2, c20, c21);
        ST(3, c30, c31); ST(4, c40, c41); ST(5, c50, c51);
#undef ST
    } else {
        float tmp[MR * NR] __attribute__((aligned(64)));
        *(v8 *)(tmp + 0 * NR) = c00; *(v8 *)(tmp + 0 * NR + 8) = c01;
        *(v8 *)(tmp + 1 * NR) = c10; *(v8 *)(tmp + 1 * NR + 8) = c11;
        *(v8 *)(tmp + 2 * NR) = c20; *(v8 *)(tmp + 2 * NR + 8) = c21;
        *(v8 *)(tmp + 3 * NR) = c30; *(v8 *)(tmp + 3 * NR + 8) = c31;
        *(v8 *)(tmp + 4 * NR) = c40; *(v8 *)(tmp + 4 * NR + 8) = c41;
        *(v8 *)(tmp + 5 * NR) = c50; *(v8 *)(tmp + 5 * NR + 8) = c51;
        for (int i = 0; i < mr; i++) {
            float *cr = c + i * ldc;
            const float *tr = tmp + i * NR;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = tr[j];
            else
                for (int j = 0; j < nr; j++) cr[j] += tr[j];
        }
    }
}

static void pack_b_panel(const float *B, int n, int pc, int kc, int j0, float *dst)
{
    int nr = n - j0 < NR ? n - j0 : NR;
    if (nr == NR) {
        for (int k = 0; k < kc; k++)
            memcpy(dst + k * NR, B + (size_t)(pc + k) * n + j0, NR * sizeof(float));
    } else {
        for (int k = 0; k < kc; k++) {
            const float *src = B + (size_t)(pc + k) * n + j0;
            float *d = dst + k * NR;
            int j = 0;
            for (; j < nr; j++) d[j] = src[j];
            for (; j < NR; j++) d[j] = 0.0f;
        }
    }
}

static void pack_a(const float *A, int n, int i0, int mc, int pc, int kc, float *dst)
{
    for (int ir = 0; ir < mc; ir += MR) {
        int mr = mc - ir < MR ? mc - ir : MR;
        float *d = dst + (size_t)ir * kc;
        if (mr == MR) {
            const float *r0 = A + (size_t)(i0 + ir + 0) * n + pc;
            const float *r1 = r0 + n, *r2 = r1 + n, *r3 = r2 + n, *r4 = r3 + n, *r5 = r4 + n;
            for (int k = 0; k < kc; k++) {
                d[0] = r0[k]; d[1] = r1[k]; d[2] = r2[k];
                d[3] = r3[k]; d[4] = r4[k]; d[5] = r5[k];
                d += MR;
            }
        } else {
            for (int k = 0; k < kc; k++) {
                int r = 0;
                for (; r < mr; r++) d[r] = A[(size_t)(i0 + ir + r) * n + pc + k];
                for (; r < MR; r++) d[r] = 0.0f;
                d += MR;
            }
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int npanels = (n + NR - 1) / NR;
    size_t bsz = (size_t)KC * npanels * NR * sizeof(float);
    bsz = (bsz + 63) & ~(size_t)63;
    float *Bp = (float *)aligned_alloc(64, bsz);

    int nib = (n + MC - 1) / MC;
    int njc = (n + NC - 1) / NC;
    int ntasks = nib * njc;

    #pragma omp parallel
    {
        size_t asz = (size_t)MC * KC * sizeof(float);
        asz = (asz + 63) & ~(size_t)63;
        float *Ap = (float *)aligned_alloc(64, asz);

        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int first = (pc == 0);

            #pragma omp for schedule(static)
            for (int jp = 0; jp < npanels; jp++)
                pack_b_panel(B, n, pc, kc, jp * NR, Bp + (size_t)jp * kc * NR);

            #pragma omp for schedule(dynamic, 1)
            for (int t = 0; t < ntasks; t++) {
                int ib = t / njc, jc = t % njc;
                int i0 = ib * MC;
                int mc = n - i0 < MC ? n - i0 : MC;
                int j0 = jc * NC;
                int jend = j0 + NC < n ? j0 + NC : n;

                pack_a(A, n, i0, mc, pc, kc, Ap);

                for (int jr = j0; jr < jend; jr += NR) {
                    int nr = n - jr < NR ? n - jr : NR;
                    const float *bp = Bp + (size_t)(jr / NR) * kc * NR;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, Ap + (size_t)ir * kc, bp,
                               C + (size_t)(i0 + ir) * n + jr, n, mr, nr, first);
                    }
                }
            }
        }
        free(Ap);
    }
    free(Bp);
}
